#!/usr/bin/env node
// V5 evidence runner: Scenarios A-E (+ B multi-owner, A with a slow owner), labelled trajectory datasets (seed 1 = dev set
// used while building; seeds 2-5 = later seeds reported separately, generated by the same author, NOT an independent
// held-out set), MOCK e-mail outbox sample and a signed periodic report with its independent re-derivation.
// usage: node scripts/v5/run-scenarios.mjs [--out docs/evidence/v5]
import { mkdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { execSync } from 'node:child_process';
import { scenarioA, scenarioB, scenarioC, scenarioD, scenarioE } from '../../src/v5/sim/scenarios.mjs';
import { runDatasets } from '../../src/v5/sim/datasets.mjs';
import { buildV5, near } from '../../src/v5/world.mjs';
import { verifyReport } from '../../src/v5/report/report.mjs';

const arg = (k, d) => { const i = process.argv.indexOf('--' + k); return i < 0 ? d : process.argv[i + 1]; };
const out = arg('out', 'docs/evidence/v5'); mkdirSync(out, { recursive: true });
const J = (o) => JSON.stringify(o, (k, v) => typeof v === 'bigint' ? v.toString() : (k === 'w' ? undefined : v), 1);
const head = (() => { try { return execSync('git rev-parse HEAD').toString().trim(); } catch { return 'unknown'; } })();
const strip = (r) => { const { w, ...x } = r ?? {}; return x; };
const t0 = Date.now();
const scen = {
  A: strip(await scenarioA()), A_slowOwner: strip(await scenarioA({ ownerResponseMs: 6 * 3600_000 })),
  B: strip(await scenarioB()), B_multiOwner: strip(await scenarioB({ multiOwner: true })),
  C: strip(await scenarioC()), D: strip(await scenarioD()), E: strip(await scenarioE()),
};
writeFileSync(join(out, 'scenarios.json'), J({ v: 'safebox.v5.scenarios', candidate: head, generatedWallMs: Date.now() - t0, scenarios: scen }));
const dev = await runDatasets({ seeds: [1] }), later = await runDatasets({ seeds: [2, 3, 4, 5] });
writeFileSync(join(out, 'datasets.json'), J({ v: 'safebox.v5.datasets', candidate: head, note: 'Synthetic personas written by the implementer. Seed 1 was used during development; seeds 2-5 were first run for this evidence file. Same generator and personas, so this is NOT an independent held-out evaluation.', dev, laterSeeds: later }));
// MOCK e-mail sandbox evidence + signed report
const w = buildV5();
for (let i = 0; i < 14; i++) { await w.pay({ credId: 'k1-phone', amountYocto: near(0.05), request: { memo: 'burst ' + i } }); await w.advance(20_000, 20_000); }
await w.advance(3600_000, 600_000);
const rep = w.report('DAILY'); await w.notify.drain();
const vr = verifyReport(rep, w.journal.reader('auditor').events(), w.reportSigner.publicKey);
writeFileSync(join(out, 'email-sandbox.json'), J({ v: 'safebox.v5.email-sandbox', candidate: head, transport: 'MockTransport (in-process; nothing leaves the container)', productionProvider: 'NOT_CONNECTED',
  sent: w.mock.sent, outbox: w.notify.stats(), report: { statement: rep.statement, verify: vr } }));
console.log(J({ out, A: scen.A.metrics, B: scen.B.metrics, D: scen.D.metrics ?? scen.D, datasetsDev: dev.summary, datasetsLater: later.summary, emails: w.mock.sent.length, reportVerify: vr }).slice(0, 6000));
